const name = $input.item.json.name;
const email = $input.item.json.email;
const message = $input.item.json.message;

let status = "Valid";

// boş alan kontrolü
if (!name || !email || !message) {
  status = "Invalid";
}

// email format kontrolü
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  status = "Invalid";
}

return [{
  json: {
    name,
    email,
    message,
    status
  }
}];

const name = $input.item.json.name;
const email = $input.item.json.email;
const message = $input.item.json.message;
const status = $input.item.json.status;

let intent = "Support";
let urgency = "Low";

const msg = message.toLowerCase();

// intent belirleme
if (msg.includes("buy") || msg.includes("price")) {
  intent = "Sales";
} else if (msg.includes("partner")) {
  intent = "Partnership";
}

// urgency belirleme
if (msg.includes("urgent") || msg.includes("asap")) {
  urgency = "High";
} else if (msg.includes("soon")) {
  urgency = "Medium";
}

return [{
  json: {
    name,
    email,
    message,
    status,
    intent,
    urgency
  }
}];

const data = {
  name: $input.item.json.name,
  email: $input.item.json.email,
  message: $input.item.json.message,
  status: $input.item.json.status,
  intent: $input.item.json.intent,
  urgency: $input.item.json.urgency
};

// simulating Google Sheets insert
console.log("Data to be inserted into Google Sheets:", data);

return [{
  json: {
    ...data,
    note: "This data would normally be stored in Google Sheets"
  }
}];
